/** Case-insensitive prefix-or-word match on the name, best matches first, at most `limit`. */
export function searchStations(q: string, limit = 6): Station[] {
  const s = q.trim().toLowerCase();
  if (s.length < 2) return [];
  return STATIONS.map((st) => {
    const n = st.name.toLowerCase();
    const score = n.startsWith(s) ? 0 : n.split(/[\s-]+/).some((w) => w.startsWith(s)) ? 1 : n.includes(s) ? 2 : 3;
    return { st, score };
  })
    .filter((x) => x.score < 3)
    .sort((a, b) => a.score - b.score || a.st.name.localeCompare(b.st.name))
    .slice(0, limit)
    .map((x) => x.st);
}
